// n8n Code node
// Mode: Run Once for All Items
// Dynamic Fillout Gmail parser.
// Captures First name, Last name, Email.
// Prevents answers like "After exploring the site..." from being treated as questions.
// Handles confirmation fields like "I confirm..." and "I will read..." correctly.

function asString(value) {
  if (value === null || value === undefined) return '';

  if (typeof value === 'string') return value;

  if (Array.isArray(value)) {
    return value.map(asString).filter(Boolean).join(', ');
  }

  if (typeof value === 'object') {
    if (value.value !== undefined) return asString(value.value);
    if (value.answer !== undefined) return asString(value.answer);
    if (value.label !== undefined) return asString(value.label);
    return JSON.stringify(value);
  }

  return String(value);
}

function clean(value) {
  return asString(value)
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .trim();
}

function stripRequiredMark(value) {
  return clean(value)
    .replace(/\s*\*+\s*$/g, '')
    .trim();
}

function normalizeKey(value) {
  return stripRequiredMark(value)
    .replace(/[’‘]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function getDeep(obj, paths) {
  for (const path of paths) {
    let cur = obj;
    let ok = true;

    for (const part of path.split('.')) {
      if (cur && Object.prototype.hasOwnProperty.call(cur, part)) {
        cur = cur[part];
      } else {
        ok = false;
        break;
      }
    }

    if (ok && cur !== undefined && cur !== null) {
      return cur;
    }
  }

  return undefined;
}

function findArrayOfAnswers(obj) {
  const candidates = [
    obj,
    obj.body,
    obj.data,
    obj.submission,
    obj.response,
    obj.payload,
    obj.body?.data,
    obj.body?.submission,
    obj.data?.submission,
  ].filter(Boolean);

  const possibleKeys = [
    'questions',
    'answers',
    'responses',
    'fields',
    'formFields',
    'questionsAndAnswers',
    'submissionQuestions',
  ];

  for (const candidate of candidates) {
    for (const key of possibleKeys) {
      if (Array.isArray(candidate[key])) {
        return candidate[key];
      }
    }
  }

  return null;
}

function extractQuestion(row) {
  return stripRequiredMark(
    row.question ||
    row.name ||
    row.label ||
    row.title ||
    row.fieldName ||
    row.field_name ||
    row.questionText ||
    row.question_text ||
    row.key
  );
}

function extractAnswer(row) {
  return clean(
    row.answer ??
    row.value ??
    row.response ??
    row.responses ??
    row.text ??
    row.values ??
    row.selected ??
    row.selectedOptions
  );
}

function parseStructuredPayload(json) {
  const arr = findArrayOfAnswers(json);

  if (!Array.isArray(arr)) return [];

  return arr
    .map(row => ({
      question: extractQuestion(row),
      answer: extractAnswer(row),
      raw: row,
    }))
    .filter(row => row.question || row.answer);
}

function extractEmailOnly(value) {
  const text = clean(value);
  const match = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return match ? match[0] : text;
}

function isExactFieldLabel(line) {
  const n = normalizeKey(line);

  const exactLabels = [
    'first name',
    'last name',
    'email',
    'email address',
    'reference 1',
    'reference 2',
  ];

  if (exactLabels.includes(n)) return true;

  const labelStarts = [
    'i will read, watch, and review',
    'i confirm that',
    'i agree to share',
    'i understand that this indicates',
    'please note:',
  ];

  return labelStarts.some(start => n.startsWith(start));
}

function isLikelyQuestion(line) {
  const l = stripRequiredMark(line);
  const n = normalizeKey(l);

  if (!l) return false;

  // Profile, confirmation, reference, and note labels.
  if (isExactFieldLabel(l)) return true;

  // Most real Fillout questions end with a question mark.
  if (n.endsWith('?')) return true;

  // Some long prompts include a question mark but may end with a link or parenthesis.
  const promptStartsThatMayNotEndWithQuestionMark = [
    'we are in the era of advanced manufacturing',
    'flolabs is also launching',
  ];

  if (
    n.includes('?') &&
    promptStartsThatMayNotEndWithQuestionMark.some(start => n.startsWith(start))
  ) {
    return true;
  }

  // Strict non-question-mark prompts from older or slightly different forms.
  // Keep this list narrow. Do not add broad starts like "after exploring".
  const strictStarts = [
    'can you please provide',
    'how does it relate',
    'how do the insights shared',
    'what did you find the most',
    'do you think any of the content',
    'can you put them in a logical sequence',
    'any other comment',
  ];

  return strictStarts.some(start => n.startsWith(start));
}

function isFooterLine(line) {
  const n = normalizeKey(line);

  return (
    n.startsWith('view submission') ||
    n.startsWith('view all') ||
    n.includes("view all of your form's submissions") ||
    n === 'responses' ||
    n === 'responses:' ||
    n === 'below is a copy of the response.' ||
    n.startsWith('you received a new submission') ||
    n.includes('powered by fillout')
  );
}

function extractResponsesBlock(text) {
  const t = clean(text);
  const idx = t.indexOf('RESPONSES:');

  if (idx === -1) return t;

  return t.slice(idx + 'RESPONSES:'.length);
}

function parseGmailText(text) {
  const block = extractResponsesBlock(text);

  const lines = block
    .split('\n')
    .map(line => line.trim())
    .filter(Boolean)
    .filter(line => !isFooterLine(line))
    .filter(line => !line.startsWith('http'))
    .filter(line => !line.startsWith('*'));

  const fields = [];
  let currentQuestion = null;
  let answerLines = [];

  function flush() {
    if (!currentQuestion) return;

    fields.push({
      question: stripRequiredMark(currentQuestion),
      answer: answerLines.join('\n').trim(),
    });

    currentQuestion = null;
    answerLines = [];
  }

  for (const line of lines) {
    const looksLikeQuestion = isLikelyQuestion(line);

    if (looksLikeQuestion) {
      // If the applicant typed the same question as an answer, do not split again.
      if (
        currentQuestion &&
        normalizeKey(line) === normalizeKey(currentQuestion) &&
        answerLines.length === 0
      ) {
        answerLines.push(line);
        continue;
      }

      flush();
      currentQuestion = line;
      answerLines = [];
    } else if (currentQuestion) {
      answerLines.push(line);
    }
  }

  flush();

  return fields;
}

function findAnswerByQuestion(fields, aliases) {
  const normalizedAliases = aliases.map(normalizeKey);

  const found = fields.find(field =>
    normalizedAliases.includes(normalizeKey(field.question))
  );

  return found ? found.answer : '';
}

return items.map(item => {
  let fields = parseStructuredPayload(item.json);
  let parseSource = 'structured';

  if (fields.length === 0) {
    fields = parseGmailText(item.json.text || '');
    parseSource = 'gmail_text';
  }

  fields = fields.map(field => {
    const question = stripRequiredMark(field.question);
    let answer = clean(field.answer);

    if (['email', 'email address'].includes(normalizeKey(question))) {
      answer = extractEmailOnly(answer);
    }

    return {
      question,
      answer,
    };
  });

  const firstName =
    clean(getDeep(item.json, ['body.firstName', 'body.first_name', 'data.firstName', 'firstName'])) ||
    findAnswerByQuestion(fields, ['First name', 'First Name']);

  const lastName =
    clean(getDeep(item.json, ['body.lastName', 'body.last_name', 'data.lastName', 'lastName'])) ||
    findAnswerByQuestion(fields, ['Last name', 'Last Name']);

  const emailRaw =
    clean(getDeep(item.json, ['body.email', 'data.email', 'email'])) ||
    findAnswerByQuestion(fields, ['Email', 'Email address']);

  const email = extractEmailOnly(emailRaw);

  item.json.formFields = fields;
  item.json.formFields_count = fields.length;

  item.json.firstName = clean(firstName);
  item.json.lastName = clean(lastName);
  item.json.email = clean(email);

  item.json.parse_source = parseSource;
  item.json.parse_ok = fields.length > 0;

  item.json.first_three_fields = fields.slice(0, 3);
  item.json.last_three_fields = fields.slice(-3);

  item.json.profile_parse_ok = Boolean(
    item.json.firstName &&
    item.json.lastName &&
    item.json.email
  );

  return item;
});

const sourceItems = $items("Node 6- AI Payload  Build Compact Q&A JSON (Connected Email)");

const banned = new Set([
  'yes',
  'no',
  'maybe',
  "i don't know",
  'idk',
  'n/a',
  'na',
  'none',
  '-',
]);

function parseJsonMaybe(raw) {
  if (!raw) return {};
  if (typeof raw === 'object') return raw;

  const s = String(raw).trim();

  try {
    return JSON.parse(s);
  } catch (e) {
    const m = s.match(/\{[\s\S]*\}/);
    if (!m) return {};

    try {
      return JSON.parse(m[0]);
    } catch (e2) {
      return {};
    }
  }
}

function validateAnswer(answer) {
  const a = String(answer || '').trim();
  const s = a.toLowerCase();

  const words = a
    .split(/\s+/)
    .filter(word => word.length >= 2);

  const uniqueWords = new Set(
    words.map(word => word.toLowerCase())
  );

  if (banned.has(s)) return 'banned_word';
  if (a.length < 12) return 'too_short';
  if (words.length < 3) return 'too_few_words';
  if (uniqueWords.size < 3) return 'repetitive_filler';

  return null;
}

function validateQA(qa) {
  let passCount = 0;
  let failCount = 0;

  const failedItems = [];
  const answerCounts = {};

  qa.forEach((row, index) => {
    const q = String(row.q || '').trim();
    const a = String(row.a || '').trim();
    const normalizedAnswer = a.toLowerCase();

    answerCounts[normalizedAnswer] = (answerCounts[normalizedAnswer] || 0) + 1;

    const reason = validateAnswer(a);

    if (reason) {
      failCount++;
      failedItems.push({
        index: index + 1,
        q,
        a,
        reason,
      });
    } else {
      passCount++;
    }
  });

  const duplicate_answers = Object.values(answerCounts)
    .some(count => count > 3);

  return {
    passCount,
    failCount,
    totalItems: qa.length,
    passRate: qa.length > 0 ? passCount / qa.length : 0,
    duplicate_answers,
    failedItems,
  };
}

return $input.all().map((item, index) => {
  const source = sourceItems[index]?.json || {};

  let qa = [];

  try {
    qa = typeof source.qa_json === 'string'
      ? JSON.parse(source.qa_json)
      : Array.isArray(source.qa_json)
        ? source.qa_json
        : [];
  } catch (e) {
    qa = [];
  }

  const aiOut = parseJsonMaybe(item.json.output);
  const result = validateQA(qa);

  let summary = aiOut.summary || '';

  if (result.totalItems === 0) {
    summary = 'No answers to validate.';
  } else if (result.passCount === result.totalItems) {
    summary = 'All answers passed validation.';
  } else if (!summary) {
    summary = 'Some answers failed validation because they were too short, had too few words, used placeholder responses, or contained repetitive filler.';
  }

  return {
    json: {
      summary,

      passCount: result.passCount,
      failCount: result.failCount,
      totalItems: result.totalItems,
      passRate: result.passRate,
      duplicate_answers: result.duplicate_answers,
      failedItems: result.failedItems,

      counts_ok: result.passCount + result.failCount === result.totalItems,

      qa_count: source.qa_count,
      qa_payload_ok: source.qa_payload_ok,
      formFields_original_count: source.formFields_original_count,
      formFields_review_count: source.formFields_review_count,
      form_structure_changed: source.form_structure_changed,

      applicant_email: source.applicant_email || source.email || '',
      applicant_name: source.applicant_name || '',
    },
  };
});

const formFields = Array.isArray(item.json.formFields)
  ? item.json.formFields
  : [];

const qa = formFields
  .map(field => ({
    q: String(field.question || '').trim(),
    a: String(field.answer || '').trim(),
  }))
  .filter(row => row.q.length > 0);

item.json.qa_json = JSON.stringify(qa);
item.json.qa_count = qa.length;

item.json.applicant_email = item.json.email || '';
item.json.applicant_name = `${item.json.firstName || ''} ${item.json.lastName || ''}`.trim();

item.json.qa_payload_ok = qa.length > 0;

return item;

const ff = Array.isArray(item.json.formFields) ? item.json.formFields : [];

function norm(value) {
  return String(value || '')
    .replace(/[’‘]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

function shouldExcludeField(field) {
  const q = norm(field.question);
  const a = norm(field.answer);

  if (!q) return true;
  if (!a) return true;

  const exactExcludes = new Set([
    'first name',
    'last name',
    'email',
    'email address',
    'reference 1',
    'reference 2',
  ]);

  if (exactExcludes.has(q)) return true;

  const excludePatterns = [
    'i will read, watch, and review',
    'i confirm that',
    'i agree to share',
    'i understand that this indicates',
    'please note:',
    'john hazlewood',
    'founder and ceo',
    'reference',
  ];

  return excludePatterns.some(pattern => q.includes(pattern));
}

const reviewFields = ff.filter(field => !shouldExcludeField(field));

item.json.formFields_original_count = ff.length;
item.json.formFields = reviewFields;
item.json.formFields_review_count = reviewFields.length;

// Warning only. Do not block the workflow because the form may change.
item.json.form_structure_changed = reviewFields.length !== 27;

return item;

