  'Phone Number',
  'Country/Region',
  'State/Region',
  'City',
  'LinkedIn URL',
  'Job title',
  'Education',
  'CV',
  'Source',
  'I added hr@flolabsinnovations.com',
];

function normalizeLabel(value = '') {
  return String(value || '')
    .replace(/\s*:\s*$/g, '')
    .trim()
    .toLowerCase();
}

const lines = textContent
  .split('\n')
  .map(line => line.trim())
  .filter(Boolean);

function isKnownLabel(line) {
  const normalized = normalizeLabel(line);
  return labels.some(label => normalizeLabel(label) === normalized);
}

function getField(label) {
  const wanted = normalizeLabel(label);

  for (let i = 0; i < lines.length; i++) {
    const current = normalizeLabel(lines[i]);

    if (current === wanted) {
      for (let j = i + 1; j < lines.length; j++) {
        if (!lines[j]) continue;
        if (isKnownLabel(lines[j])) return '';
        return cleanValue(lines[j]);
      }
    }

    // fallback لو HubSpot رجّعها بنفس السطر مثل: First Name: Abdullah
    const sameLineRegex = new RegExp(`^${label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*:\\s*(.+)$`, 'i');
    const sameLineMatch = lines[i].match(sameLineRegex);
    if (sameLineMatch) {
      return cleanValue(sameLineMatch[1]);
    }
  }

  return '';
}

function extractCvFilename() {
  const fromLink =
    String(rawBody).match(/CV[\s\S]{0,300}?<a[^>]*>(.*?)<\/a>/i)?.[1] ||
    String(rawBody).match(/<a[^>]*>([^<]*\.pdf)<\/a>/i)?.[1];

  if (fromLink) return cleanValue(fromLink);

  const cvField = getField('CV');

  if (!cvField) return '';

  // مثال:
  // my_cv-(1)-2549c9.pdf:https://api-na1.hubspot.com/...
  const pdfMatch = cvField.match(/([^\/\s:]+\.pdf)/i);
  if (pdfMatch) return cleanValue(pdfMatch[1]);

  return cleanValue(cvField.split(':')[0]);
}

const dateHeader = getHeader('Date');
const messageIdHeader = getHeader('Message-ID');
const fromHeader = getHeader('From');

return {
  message_id: sqlSafe(item.id || ''),
  hubspot_message_id: sqlSafe(item.messageId || messageIdHeader || ''),
  thread_id: sqlSafe(item.threadId || ''),
  received_at: item.date
    ? new Date(item.date).toISOString()
    : dateHeader
      ? new Date(dateHeader).toISOString()
      : '',
  from_email: sqlSafe(item?.from?.value?.[0]?.address || fromHeader || ''),

  first_name: sqlSafe(getField('First Name')),
  last_name: sqlSafe(getField('Last Name')),
  applicant_email: sqlSafe(getField('Email')).toLowerCase(),
  phone: sqlSafe(getField('Phone Number')),
  country: sqlSafe(getField('Country/Region')),
  state: sqlSafe(getField('State/Region')),
  city: sqlSafe(getField('City')),
  linkedin_url: sqlSafe(getField('LinkedIn URL')),
  job_title: sqlSafe(getField('Job title')),
  education: sqlSafe(getField('Education')),
  cv_filename: sqlSafe(extractCvFilename()),
  source: sqlSafe(getField('Source')),

  debug_body_length: textContent.length,
  debug_body_preview: textContent.slice(0, 1000),
};
